using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static class PresentationIsolation {
 const string Root="Recovery/PresentationDiagnosis_20261107";static Camera[] cameras;static bool[] enabled;static Camera game;static Vector3 pos;static Quaternion rot;static MonoBehaviour movement;static bool moving,background,maximized,finished;static int rate,vsync,phase=-1,frame=-1;static float scale;static UniversalRenderPipelineAsset pipeline;static EditorWindow window;static double start;static List<float> samples=new List<float>();static string csv="mode,frames,mean_ms,median_ms,p95_ms\n";static string[] modes={"Baseline","HalfRenderScale","NoCameras","BaselineRepeat"};
 public static object Run(){if(!EditorApplication.isPlaying)throw new Exception("Play Mode required");Directory.CreateDirectory(Root);game=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.name=="Camera");pos=game.transform.position;rot=game.transform.rotation;cameras=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None);enabled=cameras.Select(c=>c.enabled).ToArray();movement=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).FirstOrDefault(m=>m.GetType().Name=="KarakterHareket");moving=movement&&movement.enabled;if(movement)movement.enabled=false;pipeline=(UniversalRenderPipelineAsset)GraphicsSettings.currentRenderPipeline;scale=pipeline.renderScale;rate=Application.targetFrameRate;vsync=QualitySettings.vSyncCount;background=Application.runInBackground;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;Application.runInBackground=true;window=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));maximized=window.maximized;window.maximized=true;window.Focus();EditorApplication.isPaused=false;EditorApplication.playModeStateChanged+=OnState;Next();EditorApplication.update+=Tick;return "Started normal/quarter-pixel/no-camera/repeat isolation";}
 static void Restore(){pipeline.renderScale=scale;for(int i=0;i<cameras.Length;i++)if(cameras[i])cameras[i].enabled=enabled[i];}
 static void OnState(PlayModeStateChange state){if(state==PlayModeStateChange.ExitingPlayMode)Finish();}
 static void Finish(){if(finished)return;finished=true;EditorApplication.update-=Tick;EditorApplication.playModeStateChanged-=OnState;Restore();if(game)game.transform.SetPositionAndRotation(pos,rot);if(movement)movement.enabled=moving;Application.targetFrameRate=rate;QualitySettings.vSyncCount=vsync;Application.runInBackground=background;if(window)window.maximized=maximized;File.WriteAllText(Root+"/Isolation.csv",csv);File.WriteAllText(Root+"/status.txt","COMPLETE; cameras and pipeline scale restored");}
 static void Next(){Restore();phase++;if(phase>=modes.Length){Finish();return;}game.transform.SetPositionAndRotation(new Vector3(509.513f,2.235f,1248.762f),Quaternion.Euler(0,180,0));if(phase==1)pipeline.renderScale=.5f;if(phase==2)foreach(var c in cameras)c.enabled=false;samples.Clear();start=EditorApplication.timeSinceStartup;File.WriteAllText(Root+"/status.txt",modes[phase]);}
 static string N(double n){return n.ToString(System.Globalization.CultureInfo.InvariantCulture);}
 static void Tick(){try{if(!EditorApplication.isPlaying){Finish();return;}game.transform.SetPositionAndRotation(new Vector3(509.513f,2.235f,1248.762f),Quaternion.Euler(0,180,0));if(Time.frameCount==frame)return;frame=Time.frameCount;double elapsed=EditorApplication.timeSinceStartup-start;if(elapsed<3)return;if(elapsed<7){samples.Add(Time.unscaledDeltaTime*1000);return;}samples.Sort();int n=samples.Count;if(n>0)csv+=String.Join(",",modes[phase],n,N(samples.Average()),N(samples[n/2]),N(samples[Math.Min(n-1,(int)(n*.95))]))+"\n";File.WriteAllText(Root+"/Isolation.csv",csv);Next();}catch(Exception e){Finish();File.WriteAllText(Root+"/status.txt","ERROR "+e);}}
}
